import { MeshStandardNodeMaterial, Mesh, Group, PlaneGeometry, Color } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

/**
 * @param {any} config - node configuration
 * @param {any} ctx - runtime context
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  // Geometry for the capsule‑like badge
  const geometry = new PlaneGeometry(0.8, 0.3);

  // Base material (uses lighting for accent emissive edge)
  const material = new MeshStandardNodeMaterial();
  const colors = (config.intent && config.intent.visualSpec && config.intent.visualSpec.colors) || {};

  // Base colour (paper) and accent emissive edge
  material.color = new Color(colors.paper ?? '#e8ecf2');
  material.emissive = new Color(colors.accent ?? '#ff2a38');
  material.emissiveIntensity = 0.5;
  material.roughness = 0.7;
  material.metalness = 0.0;

  // Load the grain texture if provided
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Store timelines for cleanup
  const activeTimelines = [];

  // Interaction handlers
  const handlers = {
    hover: () => {
      const baseY = group.position.y;
      const tl = gsap.timeline({ defaults: { duration: 0.3, ease: 'power3.out' } });
      tl.to(group.position, { y: baseY + 0.15 });
      activeTimelines.push(tl);
    },
    click: () => {
      ctx.emit('hub-pricing.select', {});
    },
  };
  group.userData.handlers = handlers;

  // Cleanup routine
  group.userData.cleanup = () => {
    geometry.dispose();
    if (loadedTexture) loadedTexture.dispose();
    material.dispose();

    activeTimelines.forEach((tl) => tl.kill());
    activeTimelines.length = 0;
  };

  // Apply cinematic primitives if any (none in this spec)
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (ctx.primitives && typeof ctx.primitives[prim.name] === 'function') {
        const { cleanup, timeline } = ctx.primitives[prim.name](group, prim.params || {});
        // store for later cleanup
        if (timeline) activeTimelines.push(timeline);
        if (cleanup) {
          const prev = group.userData.cleanup;
          group.userData.cleanup = () => {
            prev();
            cleanup();
          };
        }
      }
    }
  }

  return group;
}
